import{c as s,$ as d,Q as c,j as n,g as a,n as h,o as e,m as o}from"./chunks/framework.Xjf2pjgg.js";const f=JSON.parse('{"title":"YuPay 安装部署","description":"","frontmatter":{"title":"YuPay 安装部署"},"headers":[],"relativePath":"plugins/items/yupay/install.md","filePath":"plugins/items/yupay/install.md"}'),p={name:"plugins/items/yupay/install.md"},u={class:"quick-actions"};function y(b,t,k,m,P,g){const i=d("CopyMarkdownButton"),l=d("CopyLLMButton"),r=d("InstallCommand");return c(),n("div",null,[t[0]||(t[0]=a("h1",{id:"yupay-安装部署",tabindex:"-1"},[h("YuPay 安装部署 "),a("a",{class:"header-anchor",href:"#yupay-安装部署","aria-label":'Permalink to "YuPay 安装部署"'},"​")],-1)),a("div",u,[e(i,{page:""}),e(l,{page:""})]),t[1]||(t[1]=o('<p>YuPay 是微信支付与支付宝官方商户直连插件，不需要第三方代收。安装重点不是“把 jar 放进去”这么简单，而是要准备好商户资料、证书、公网回调地址和安全检查。</p><h2 id="环境要求" tabindex="-1">环境要求 <a class="header-anchor" href="#环境要求" aria-label="Permalink to &quot;环境要求&quot;">​</a></h2><table tabindex="0"><thead><tr><th>检查项</th><th>要求</th></tr></thead><tbody><tr><td>Java</td><td><code>JDK 8</code> 及以上</td></tr><tr><td>服务端</td><td>Bukkit/Spigot/Paper 及常见衍生端</td></tr><tr><td>当前版本</td><td><code>1.5.0.0</code></td></tr><tr><td>必要网络</td><td>服务端需要能访问微信支付/支付宝接口；支付平台需要能访问你的回调地址</td></tr><tr><td>数据库</td><td>单服可用 SQLite；群组服、跨服发奖或多实例回调建议 MySQL</td></tr><tr><td>软依赖</td><td>Vault、PlaceholderAPI、PlayerPoints、ProtocolLib</td></tr></tbody></table><p>软依赖不是全部必装：</p><table tabindex="0"><thead><tr><th>插件</th><th>作用</th></tr></thead><tbody><tr><td><code>Vault</code></td><td>使用主流经济插件发放赞助点数或货币。</td></tr><tr><td><code>PlayerPoints</code></td><td>使用点券类经济奖励。</td></tr><tr><td><code>PlaceholderAPI</code></td><td>在菜单、计分板、聊天里显示赞助金额、排行和卡密状态。</td></tr><tr><td><code>ProtocolLib</code></td><td>地图二维码输出模式需要。没有它时建议使用 <code>link</code> 或 <code>text</code> 输出。</td></tr></tbody></table><h2 id="部署步骤" tabindex="-1">部署步骤 <a class="header-anchor" href="#部署步骤" aria-label="Permalink to &quot;部署步骤&quot;">​</a></h2><ol><li>将发布版 <code>YuPay-版本.jar</code> 放入服务端 <code>plugins/</code> 目录。</li><li>启动一次服务端，让插件生成 <code>plugins/YuPay/config.yml</code>、语言文件、数据目录和证书目录。</li><li>停服或执行 <code>/yp reload</code> 前，先在 <code>config.yml</code> 中完成支付渠道、回调、数据库和奖励配置。</li><li>把微信/支付宝所需证书文件放到 YuPay 数据目录下对应位置。</li><li>确认公网域名或 IP 能访问回调端口，云服务器安全组和系统防火墙都已放行。</li><li>重启服务端，执行 <code>/yp health full</code> 检查数据库、依赖、支付渠道和回调状态。</li><li>使用小额订单完整测试：创建订单、扫码支付、回调入账、奖励发放、订单查询、退款申请和管理员审核。</li></ol><h2 id="安装命令" tabindex="-1">安装命令 <a class="header-anchor" href="#安装命令" aria-label="Permalink to &quot;安装命令&quot;">​</a></h2>',8)),e(r,{slug:"yupay"}),t[2]||(t[2]=o(`<h2 id="支付资料准备" tabindex="-1">支付资料准备 <a class="header-anchor" href="#支付资料准备" aria-label="Permalink to &quot;支付资料准备&quot;">​</a></h2><h3 id="微信支付" tabindex="-1">微信支付 <a class="header-anchor" href="#微信支付" aria-label="Permalink to &quot;微信支付&quot;">​</a></h3><table tabindex="0"><thead><tr><th>资料</th><th>配置项</th><th>获取位置</th></tr></thead><tbody><tr><td>商户号</td><td><code>wechat.mchid</code></td><td>微信支付商户平台，账户中心 -&gt; 商户信息</td></tr><tr><td>AppID</td><td><code>wechat.appid</code></td><td>微信公众平台或小程序/服务号后台</td></tr><tr><td>商户 API 证书序列号</td><td><code>wechat.serial-no</code></td><td>微信支付商户平台，账户中心 -&gt; API 安全</td></tr><tr><td>商户私钥</td><td><code>wechat.private-key-path</code></td><td>API 证书生成后的 <code>apiclient_key.pem</code></td></tr><tr><td>微信支付平台公钥</td><td><code>wechat.public-key-path</code></td><td>商户平台下载或按官方流程获取</td></tr><tr><td>平台公钥 ID</td><td><code>wechat.public-key-id</code></td><td>微信支付平台公钥信息</td></tr><tr><td>API v3 密钥</td><td><code>wechat.api-v3-key</code></td><td>商户平台，API 安全 -&gt; APIv3 密钥</td></tr><tr><td>支付回调地址</td><td><code>wechat.notify-url</code></td><td>你的公网 HTTP/HTTPS 地址</td></tr><tr><td>退款回调地址</td><td><code>wechat.refund-notify-url</code></td><td>建议与支付回调分开路径</td></tr></tbody></table><h3 id="支付宝" tabindex="-1">支付宝 <a class="header-anchor" href="#支付宝" aria-label="Permalink to &quot;支付宝&quot;">​</a></h3><table tabindex="0"><thead><tr><th>资料</th><th>配置项</th><th>说明</th></tr></thead><tbody><tr><td>应用 ID</td><td><code>alipay.app-id</code></td><td>支付宝开放平台应用信息</td></tr><tr><td>应用私钥</td><td><code>alipay.merchant-private-key</code></td><td>去掉 <code>BEGIN/END PRIVATE KEY</code> 头尾</td></tr><tr><td>支付宝公钥</td><td><code>alipay.alipay-public-key</code></td><td>公钥模式使用</td></tr><tr><td>应用公钥证书</td><td><code>alipay.app-cert-path</code></td><td>证书模式使用</td></tr><tr><td>支付宝公钥证书</td><td><code>alipay.alipay-cert-path</code></td><td>证书模式使用</td></tr><tr><td>支付宝根证书</td><td><code>alipay.alipay-root-cert-path</code></td><td>证书模式使用</td></tr><tr><td>异步通知地址</td><td><code>alipay.notify-url</code></td><td>必须公网可访问</td></tr><tr><td>同步返回地址</td><td><code>alipay.return-url</code></td><td>玩家支付完成后的浏览器返回地址</td></tr></tbody></table><p>支付宝推荐使用证书模式；如果你使用公钥模式，请确认公钥与应用私钥是一组。</p><h2 id="回调地址要求" tabindex="-1">回调地址要求 <a class="header-anchor" href="#回调地址要求" aria-label="Permalink to &quot;回调地址要求&quot;">​</a></h2><p>YuPay 内置回调服务默认监听：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">callback</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.0.0.0&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8080</span></span></code></pre></div><p>上线前确认：</p><ul><li><code>notify-url</code> 和 <code>refund-notify-url</code> 指向公网可访问地址，而不是内网地址或 <code>localhost</code>。</li><li>云服务器安全组、系统防火墙、面板防火墙都已放行回调端口。</li><li>如果使用反向代理，必须允许支付平台的 <code>POST</code> 请求原样转发到 YuPay。</li><li>支付回调和退款回调建议使用不同路径，方便审计和排查。</li><li>排查阶段可以打开 <code>callback.access-log: true</code>，稳定后再关闭减少日志量。</li></ul><h2 id="单服与群组服部署" tabindex="-1">单服与群组服部署 <a class="header-anchor" href="#单服与群组服部署" aria-label="Permalink to &quot;单服与群组服部署&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>建议</th></tr></thead><tbody><tr><td>单服</td><td>使用默认 SQLite 即可，回调和发奖都在同一服务端完成。</td></tr><tr><td>多子服但只在主服收款</td><td>主服部署 YuPay 并处理回调，其他服通过命令或外部系统联动。</td></tr><tr><td>群组服跨服发奖</td><td>使用 MySQL，所有子服配置不同 <code>cross-server.server-id</code>，并共享同一 <code>shared-secret</code>。</td></tr><tr><td>多实例接收回调</td><td>必须使用 MySQL，并确认订单与发奖流程具备幂等性。</td></tr></tbody></table><h2 id="上线前检查" tabindex="-1">上线前检查 <a class="header-anchor" href="#上线前检查" aria-label="Permalink to &quot;上线前检查&quot;">​</a></h2><ul><li>至少启用一个支付渠道，并确认示例商户号、示例密钥、示例回调地址都已替换。</li><li><code>pay.min-amount</code>、<code>pay.max-amount</code>、<code>pay.max-daily-amount</code> 符合服务器赞助规则。</li><li>奖励命令不要包含危险的全服 OP、权限组误授予或重复发放风险。</li><li><code>logging.mask-sensitive</code>、<code>logging.mask-ip</code>、<code>api.audit-log</code> 建议保持开启。</li><li>生产服上线前备份 <code>plugins/YuPay/</code> 与数据库。</li><li>完成小额支付、取消后到账、奖励失败重试、退款申请、直接退款和卡密核销测试。</li></ul><h2 id="常用检查命令" tabindex="-1">常用检查命令 <a class="header-anchor" href="#常用检查命令" aria-label="Permalink to &quot;常用检查命令&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/yp health summary</span></span>
<span class="line"><span>/yp health full</span></span>
<span class="line"><span>/yp orders</span></span>
<span class="line"><span>/yp order abnormal</span></span>
<span class="line"><span>/yp audit security 50</span></span></code></pre></div><p>如果健康检查提示支付渠道不可用，优先检查商户参数、证书路径、回调地址和服务器出站网络。</p>`,18))])}const x=s(p,[["render",y]]);export{f as __pageData,x as default};
